import pytest


def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` per-line config text.

    Each line is split on its first "=". Whitespace around the name and
    the value is stripped, and the value may itself contain "=". Lines
    without "=" are ignored. If the key appears more than once, the first
    occurrence wins. Returns "" when the key is absent. Key matching is
    exact and case-sensitive. Does not read files.
    """
    for raw in text.splitlines():
        name, sep, value = raw.partition("=")
        if sep and name.strip() == key:
            return value.strip()
    return ""


def test_basic_lookup() -> None:
    assert config_value("a=1\nb=2\nc=3", "b") == "2"


def test_missing_key_returns_empty() -> None:
    assert config_value("a=1\nb=2", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_empty_value_is_empty_string() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_whitespace_stripped() -> None:
    assert config_value("  name  =  hello world  \nb=2", "name") == "hello world"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?a=b&c=d", "url") == "http://x/?a=b&c=d"


def test_lines_without_equals_ignored() -> None:
    assert config_value("garbage\na=1\n\nmore garbage", "a") == "1"
    assert config_value("garbage", "garbage") == ""


def test_first_occurrence_wins() -> None:
    assert config_value("a=1\na=2", "a") == "1"


def test_exact_case_sensitive_match() -> None:
    assert config_value("Key=1", "key") == ""
    assert config_value("ab=1\na=2", "a") == "2"


def test_key_only_matches_name_not_value() -> None:
    assert config_value("a=b\nb=c", "b") == "c"


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


@pytest.mark.parametrize(
    ("text", "key", "expected"),
    [
        ("x=1", "x", "1"),
        ("x = 1", "x", "1"),
        ("\n\nx=1\n", "x", "1"),
        ("x=1", "", ""),
    ],
)
def test_parametrized(text: str, key: str, expected: str) -> None:
    assert config_value(text, key) == expected

